 targets={'title':(60,True),'name':(31,True),'next':(40,True),'clock':(40,False),'time':(27,False),'previous':(25,False),'badge':(26,True),'value':(25,True),'resolution':(21,True),'language':(22,True),'caption':(20,False),'date':(25,False)}
